public String c(String str) {
    String strSubstring = str.substring(0, 10);
    String strSubstring2 = str.substring(10);
    String str2 = "";
    int i = 0;
    for (int i2 = 0; i2 < strSubstring2.length(); i2++) {
        int iCharAt = (strSubstring.charAt(i) - '0') + (strSubstring2.charAt(i2) - '0');
        if (iCharAt > 9) {
            iCharAt -= 10;
        }
        str2 = String.valueOf(str2) + iCharAt;
        i++;
        if (i > 9) {
            i = 0;
        }
    }
    return str2;
}
